from pathlib import Path
import json, os, time
tid='DEV-PRED-A2Z-R4P3-ASTRA-PREBUILD-QUEUE-20261008-N1E138'
home=Path.home()
state=home/'.local/state/prediction-project-executor'/f'{tid}.json'
bus=home/'.local/state/prediction-command-bus/tasks'/f'{tid}.json'
work=home/'.local/share/prediction-project-executor/worktrees'/tid
expected=work/'control/dev_checks/a2z_next_request.json'
runtime_req=home/'.local/share/prediction-project-executor/campaigns/FULL-A2Z-LIVE-20261004-V4/requests/A2Z-V4-ASTRA-PREBUILD-DIRECT-20261008-R4P3.json'
parts=[]
def add(k,v): parts.append(f'{k}={v}')
for label,p in [('EXEC_STATE',state),('BUS_STATE',bus),('WORKTREE',work),('WORKTREE_NEXT',expected),('RUNTIME_REQUEST',runtime_req)]:
    add(label+'_EXISTS',int(p.exists()))
    if p.exists():
        try: add(label+'_MTIME_AGE_S',round(time.time()-p.stat().st_mtime,1))
        except Exception: pass
for label,p in [('EXEC',state),('BUS',bus)]:
    if p.is_file():
        try:
            o=json.loads(p.read_text())
            for k in ['status','exit_code','error','detail','claimed_at_utc','finished_at_utc','source_commit','worktree','branch']:
                if k in o: add(label+'_'+k.upper(),str(o.get(k)).replace('|','/'))
        except Exception as e: add(label+'_READ_ERROR',type(e).__name__)
if expected.is_file():
    try:
        o=json.loads(expected.read_text())
        for k in ['task_id','phase','model','model_policy','candidate_id']:
            if k in o: add('NEXT_'+k.upper(),str(o.get(k)).replace('|','/'))
    except Exception as e: add('NEXT_READ_ERROR',type(e).__name__)
matches=[]
proc=Path('/proc')
for p in proc.iterdir():
    if not p.name.isdigit(): continue
    try:
        raw=(p/'cmdline').read_bytes().replace(b'\x00',b' ').decode('utf-8','ignore')
    except Exception: continue
    if tid in raw: matches.append(p.name+':'+raw[:500].replace('|','/'))
add('ACTIVE_PROC_COUNT',len(matches))
for i,m in enumerate(matches[:5],1): add(f'ACTIVE_PROC_{i}',m)
print('ERROR_CLASS=R4P3_CLAIM_DIAG')
print('ERROR='+'|'.join(parts))
raise SystemExit(1)
